'use strict'
/**
 * 📲 تثبيت الموقع كتطبيق (PWA) — اسم التطبيق: Nami
 *
 * إضافة فقط، لا تغيّر أي منطق:
 *  - manifest لكل لاعب:  GET /u/:code/manifest.webmanifest   (يفتح التطبيق على صفحة اللاعب)
 *  - أيقونتان:            GET /pwa/nami-192.png  و  /pwa/nami-512.png
 *  - لا Service Worker، لا تخزين مسبق، لا اعتراض لأي طلب، لا قراءة من قاعدة البيانات.
 *
 * الاستخدام:
 *  const PWA = require('./sitePwa')
 *  ... داخل <head> بعد ${TITLES.HEAD}:  ${PWA.HEAD}
 *  ... داخل registerCharacterSite:       PWA.mount(app, { CODE_RE })
 */

const APP_NAME = 'Nami'
const BG = '#0a0d16'

const ICONS = {
    192: Buffer.from('', 'base64'),
    512: Buffer.from('', 'base64')
}

// يضيف رابط الـ manifest حسب كود اللاعب الموجود في العنوان (/u/<code>/... أو /login?code=<code>)
const HEAD =
    '<link rel="apple-touch-icon" href="/pwa/nami-192.png">' +
    '<meta name="apple-mobile-web-app-capable" content="yes">' +
    '<meta name="mobile-web-app-capable" content="yes">' +
    '<meta name="apple-mobile-web-app-title" content="' + APP_NAME + '">' +
    '<meta name="application-name" content="' + APP_NAME + '">' +
    '<script>(function(){try{var p=location.pathname.split("/"),' +
    'c=p[1]==="u"?p[2]:new URLSearchParams(location.search).get("code");' +
    'if(c&&/^[a-f0-9]{10}$/.test(c)){var l=document.createElement("link");' +
    'l.rel="manifest";l.href="/u/"+c+"/manifest.webmanifest";document.head.appendChild(l)}}catch(e){}})()</script>'

function mount(app, { CODE_RE }) {
    app.get('/u/:code/manifest.webmanifest', (req, res) => {
        const code = String(req.params.code || '')
        if (!CODE_RE.test(code)) return res.status(404).end()
        const start = `/u/${code}`
        res.set({
            'Content-Type': 'application/manifest+json; charset=utf-8',
            'Cache-Control': 'public, max-age=3600',
            'X-Content-Type-Options': 'nosniff'
        })
        res.send(JSON.stringify({
            id: start,
            name: APP_NAME,
            short_name: APP_NAME,
            lang: 'ar',
            dir: 'rtl',
            start_url: start,
            scope: '/',
            display: 'standalone',
            background_color: BG,
            theme_color: BG,
            icons: [
                { src: '/pwa/nami-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
                { src: '/pwa/nami-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
                { src: '/pwa/nami-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' }
            ]
        }))
    })

    for (const size of [192, 512]) {
        app.get(`/pwa/nami-${size}.png`, (req, res) => {
            res.set({ 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=604800', 'X-Content-Type-Options': 'nosniff' })
            res.send(ICONS[size])
        })
    }
}

module.exports = { HEAD, mount }
